use std::{env,fs,io,path,time};use sha2::{Sha256,Digest};use io::{BufRead,Write};const L:&str="stonix.lock";const S:&str="stonix.dat";fn main(){if path::Path::new(L).exists(){return};fs::File::create(L).ok();let a:Vec<String>=env::args().collect();if a.len()>1&&a[1]=="--stress"{s(1000000)}else if a.len()>1&&a[1]=="--verify"{v()}else{println!("Uso: --stress | --verify")};fs::remove_file(L).ok();}fn s(c:u32){let t=time::Instant::now();let f=fs::OpenOptions::new().create(true).write(true).truncate(true).open(S).unwrap();let mut w=io::BufWriter::new(f);for i in 0..c{let d=format!("DATA_{}:OK",i);let mut h=Sha256::new();h.update(d.as_bytes());let r=format!("{:x}",h.finalize());writeln!(w,"{}|{}",d,r).unwrap();}w.flush().ok();println!("TIME:{:?}|SIZE:{:.2}MB",t.elapsed(),fs::metadata(S).unwrap().len() as f64/1e6);}fn v(){let t=time::Instant::now();let f=fs::File::open(S).unwrap();let (mut o,mut e)=(0,0);for l in io::BufReader::new(f).lines().flatten(){let p:Vec<&str>=l.split('|').collect();let mut h=Sha256::new();h.update(p[0].as_bytes());if format!("{:x}",h.finalize())==p[1]{o+=1}else{e+=1}}println!("OK:{}|ERR:{}|TIME:{:?}",o,e,t.elapsed());}